interface OAuthProfile {
  providerId: string
  email: string
  name: string
  picture: string
  locale: string
}

interface UpsertResult {
  user: User
  isNewUser: boolean
}

@Injectable()
export class AuthService {
  constructor(
    @InjectRepository(User)
    private readonly usersRepository: Repository<User>,
  ) {}

  async upsertOAuthUser(profile: OAuthProfile): Promise<UpsertResult> {
    // Read #1: try to find the user by the OAuth provider id.
    let user = await this.usersRepository.findOne({
      where: { providerId: profile.providerId },
    })

    let isNewUser = false

    if (!user) {
      // Read #2: fall back to an email match (sequential, only on miss).
      user = await this.usersRepository.findOne({
        where: { email: profile.email },
      })

      if (!user) {
        user = this.usersRepository.create({
          providerId: profile.providerId,
          email: profile.email,
          name: profile.name,
          picture: profile.picture,
          locale: profile.locale,
        })
        isNewUser = true
      } else {
        user.providerId = profile.providerId
      }
    }

    // Unconditional write: always refresh the profile fields and save,
    // even when nothing about the user actually changed.
    user.name = profile.name
    user.picture = profile.picture
    user.locale = profile.locale
    user = await this.usersRepository.save(user)

    return { user, isNewUser }
  }
}
